dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "variant",
      "label": "Variant (CHR:POS:REF:ALT)",
      "type": "input"
    }
  ],
  "sections": [
    {
      "section id": "variant_phewas",
      "header": "Variant PheWAS",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "phewas-associations",
        "parameters": [
          "variant"
        ],
        "cumulate data": "false",
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "visualizer": {
        "label": "",
        "type": "phewas plot",
        "group by": "Ancestry",
        "y axis field": "logP",
        "convert y -log10": "false",
        "y ticks decimal point": "2",
        "render by": "Phenotype",
        "y axis label": "-Log10(P-value)",
        "x axis label": "Phenotype",
        "beta field": "Beta",
        "hover content": [
          "Phenotype",
          "P-value",
          "Beta"
        ],
        "thresholds": [
          0.75
        ],
        "label in black": "greater than",
        "height": 350,
        "plot margin": {
          "top": 250,
          "bottom": 200,
          "left": 150,
          "right": 175
        }
      },
      "filters": [
        {
          "field": "P-value",
          "label": "P-value (<=)",
          "type": "search lower than",
          "label in bubble": "true"
        }
      ],
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "P-value",
            "raw field": "pValue"
          },
          {
            "type": "calculate",
            "field name": "logP",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "Standard error",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Sample size",
            "raw field": "n"
          },
          {
            "type": "replace characters",
            "field name": "Ancestry",
            "raw field": "ancestry",
            "replace": [
                {
                    "from": "Mixed",
                    "to": "All ancestries"
                }
            ]
          },
          {
            "type": "raw",
            "field name": "Clump",
            "raw field": "clump"
          }
        ],
        "top rows": [
          "Phenotype",
          "P-value",
          "Beta",
          "Standard error",
          "Sample size",
          "Ancestry"
        ]
      }
    },
    {
      "section id": "favor_basic",
      "header": "FAVOR basic information",
      "data point": {
        "type": "bioindex",
        "url": "https://igvf.hugeampkpnbi.org/lipids/api/bio/",
        "index": "favor-basic",
        "parameters": [
          "variant"
        ],
        "cumulate data": "false",
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Variant ID",
            "raw field": "varId"
          },
          {
            "type": "raw",
            "field name": "RSID",
            "raw field": "rsid"
          },
          {
            "type": "raw",
            "field name": "Chromosome",
            "raw field": "CHROM"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "POS"
          },
          {
            "type": "raw",
            "field name": "Reference allele",
            "raw field": "REF"
          },
          {
            "type": "raw",
            "field name": "Alternate allele",
            "raw field": "ALT"
          },
          {
            "type": "raw",
            "field name": "AF (1KG EU)",
            "raw field": "tg_eur"
          },
          {
            "type": "raw",
            "field name": "Gencode comprehensive category",
            "raw field": "genecode_comprehensive_category"
          },
          {
            "type": "raw",
            "field name": "Gencode comprehensive info",
            "raw field": "genecode_comprehensive_info"
          }
        ],
        "top rows": [
          "Variant ID",
          "RSID",
          "Chromosome",
          "Position", 
          "Reference allele",
          "Alternate allele",
          "AF (1KG EU)",
          "Gencode comprehensive category",
          "Gencode comprehensive info"
        ]
      }
    },
    {
      "section id": "favor_annot_2",
      "header": "FAVOR basic scores",
      "data point": {
        "type": "bioindex",
        "url": "https://igvf.hugeampkpnbi.org/lipids/api/bio/",
        "index": "favor-annot",
        "parameters": [
          "variant"
        ],
        "cumulate data": "false",
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Variant ID",
            "raw field": "varId"
          },
          {
            "type": "raw",
            "field name": "Annotation",
            "raw field": "Annotation"
          },
          {
            "type": "raw",
            "field name": "Score",
            "raw field": "Score"
          },
          {
            "type": "raw",
            "field name": "Annotation group",
            "raw field": "Annotation_group"
          },
          {
            "type": "raw",
            "field name": "Integrative",
            "raw field": "Integrative"
          },
          {
            "type": "join",
            "field name": "Integrative filter",
            "fields to join": ["varId", "Integrative"],
            "join by": ""
          }
        ],
        "top rows": [
          "Variant ID",
          "Annotation",
          "Score",
          "Annotation group"
        ]
      },
      "pre filters": [
        {
          "field": "Integrative filter",
          "value": "undefined",
          "type": "search"
        }
      ]
    },
    {
      "section id": "favor_annot",
      "header": "FAVOR integrated scores",
      "data point": {
        "type": "bioindex",
        "url": "https://igvf.hugeampkpnbi.org/lipids/api/bio/",
        "index": "favor-annot",
        "parameters": [
          "variant"
        ],
        "cumulate data": "false",
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Variant ID",
            "raw field": "varId"
          },
          {
            "type": "raw",
            "field name": "Annotation",
            "raw field": "Annotation"
          },
          {
            "type": "raw",
            "field name": "Score",
            "raw field": "Score"
          },
          {
            "type": "raw",
            "field name": "Annotation group",
            "raw field": "Annotation_group"
          },
          {
            "type": "raw",
            "field name": "Integrative",
            "raw field": "Integrative"
          }
        ],
        "top rows": [
          "Variant ID",
          "Annotation",
          "Score",
          "Annotation group"
        ]
      },
      "pre filters": [
        {
          "field": "Integrative",
          "value": "1.0",
          "type": "search"
        }
      ],
      "visualizer": {
        "label": "Annotations for ($variant)",
        "type": "phewas plot",
        "group by": "Annotation group",
        "y axis field": "Score",
        "convert y -log10": null,
        "y ticks decimal point": "2",
        "render by": "Annotation",
        "y axis label": "Phred-scale score",
        "x axis label": "Annotation",
        "beta field": null,
        "hover content": [
          "Annotation",
          "Annotation group",
          "Score"
        ],
        "thresholds": [],
        "height": 350,
        "plot margin": {
          "top": 250,
          "bottom": 200,
          "left": 150,
          "right": 175
        }
      }
    },
    {
      "section id": "v2f_scores",
      "header": "Variant To Function (V2F) Scores",
      "data point": {
        "type": "bioindex",
        "url": "https://igvf.hugeampkpnbi.org/lipids/api/bio/",
        "index": "v2f-scores",
        "parameters": [
          "variant"
        ],
        "cumulate data": "false",
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          },
          {
            "type": "raw",
            "field name": "Biosample type",
            "raw field": "biosampleType"
          },
          {
            "type": "raw",
            "field name": "V2F score",
            "raw field": "probScore"
          },
          {
            "type": "raw",
            "field name": "Bin score",
            "raw field": "binScore"
          },
          {
            "type": "raw",
            "field name": "Assay",
            "raw field": "assay"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Collection",
            "raw field": "collection"
          },
          {
            "type": "join multi",
            "field name": "Tissue:Biosample:Dataset",
            "fields to join": [
              "tissue",
              "biosample",
              "dataset"
            ],
            "join by": [
              ": ",
              ": "
            ]
          }
        ],
        "top rows": [
          "Tissue",
          "Biosample",
          "V2F score",
          "Dataset"
        ],
        "column formatting": {
          "Prob score": {
            "type": [
              "scientific notation"
            ]
          }
        }
      },
      "filters": [
        {
          "field": "Prob score",
          "label": "Prob score(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Dataset",
          "label": "Dataset",
          "type": "checkbox",
          "label in bubble": "true"
        }
      ],
      "visualizer": {
        "label": "",
        "type": "phewas plot",
        "group by": "Tissue",
        "y axis field": "V2F score",
        "convert y -log10": null,
        "y ticks decimal point": "2",
        "render by": "Tissue:Biosample:Dataset",
        "y axis label": "Prob score",
        "x axis label": "Tissue:Biosample:Dataset",
        "beta field": null,
        "hover content": [
          "Tissue",
          "Biosample",
          "Biosample type",
          "V2F score",
          "Bin score",
          "Assay",
          "Dataset",
          "Collection"
        ],
        "thresholds": [],
        "label in black": "greater than",
        "height": 350,
        "plot margin": {
          "top": 250,
          "bottom": 200,
          "left": 150,
          "right": 175
        }
      }
    }
  ]
}
